use std::{fs,path::Path};fn main(){let r=Path::new("/home/ubuntu/src/zopro-perf-work/early-x175");let p=r.join("capture.rs");let s=fs::read_to_string(&p).unwrap();let a="for(v,field,core)in[(\"off\",33,128),(\"on\",34,129)]{for(s,n)";let b="for(v,field,core)in[(\"off\",33,128),(\"on\",34,129)]{let base_dir=if v==\"off\"{\"initial-native\"}else{\"native\"};for(s,n)";assert_eq!(s.matches(a).count(),1);let s=s.replace(a,b).replace("native/{s}-{v}/tests.json","{base_dir}/{s}-{v}/tests.json").replace("native/{s}-{v}/{f}","{base_dir}/{s}-{v}/{f}").replace("let mut order:(Vec<usize>)=","let mut order:Vec<usize>=");fs::write(p,s).unwrap();}
